'use strict';
function main(){
var m=76.2, Vf=24.2/1000, rho=1025, g=9.81;
var need=m*g, have=Vf*rho*g;
return {body_mass_kg:m, foam_volume_l:24.2, buoyant_force_n:Math.round(have), weight_n:Math.round(need), floats:have>need};
}
try{var out=main();console.log(JSON.stringify(out));}catch(e){console.log(JSON.stringify({error:String(e&&e.message||e)}));process.exitCode=1;}

